/* Reset and base styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary-color: #2563eb;
  --accent-color: #059669;
  --text-primary: #1f2937;
  --text-secondary: #6b7280;
  --text-muted: #9ca3af;
  --bg-primary: #ffffff;
  --bg-secondary: #f9fafb;
  --bg-tertiary: #f3f4f6;
  --border-color: #e5e7eb;
  --border-hover: #d1d5db;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1);
  --radius: 0.5rem;
  --radius-lg: 0.75rem;
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --text-primary: #f9fafb;
    --text-secondary: #d1d5db;
    --text-muted: #9ca3af;
    --bg-primary: #111827;
    --bg-secondary: #1f2937;
    --bg-tertiary: #374151;
    --border-color: #374151;
    --border-hover: #4b5563;
  }
}

body {
  font-family: var(--font-family);
  color: var(--text-primary);
  background-color: var(--bg-primary);
  line-height: 1.6;
  font-size: 16px;
}

/* Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

.content-wrapper {
  max-width: 800px;
  margin: 0 auto;
}

/* Header */
.header {
  background-color: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(10px);
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
  text-decoration: none;
}

.nav {
  display: flex;
  gap: 2rem;
  list-style: none;
}

.nav a {
  color: var(--text-secondary);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.2s;
}

.nav a:hover,
.nav a.active {
  color: var(--primary-color);
}

/* Main content */
.main {
  padding: 2rem 0;
  min-height: calc(100vh - 120px);
}

/* Article cards */
.posts-grid {
  display: grid;
  gap: 2rem;
  margin-bottom: 2rem;
}

.post-card {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  transition: all 0.2s;
  box-shadow: var(--shadow-sm);
}

.post-card:hover {
  border-color: var(--border-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.post-card-header {
  margin-bottom: 1rem;
}

.post-title {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.post-title a {
  color: var(--text-primary);
  text-decoration: none;
}

.post-title a:hover {
  color: var(--primary-color);
}

.post-meta {
  display: flex;
  align-items: center;
  gap: 1rem;
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

.post-date,
.post-reading-time {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.post-excerpt {
  color: var(--text-secondary);
  margin-bottom: 1rem;
  line-height: 1.6;
}

.post-tags {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.tag {
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius);
  font-size: 0.75rem;
  text-decoration: none;
  transition: all 0.2s;
}

.tag:hover {
  background: var(--primary-color);
  color: white;
}

/* Search and filters */
.search-controls {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.search-input {
  flex: 1;
  min-width: 200px;
  padding: 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 1rem;
}

.search-input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgb(37 99 235 / 0.1);
}

.filter-select {
  padding: 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 1rem;
  min-width: 120px;
}

/* Article content */
.article-header {
  text-align: center;
  margin-bottom: 3rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--border-color);
}

.article-title {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text-primary);
}

.article-meta {
  display: flex;
  justify-content: center;
  gap: 2rem;
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

.article-tags {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.article-content {
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--text-primary);
}

.article-content h1,
.article-content h2,
.article-content h3,
.article-content h4,
.article-content h5,
.article-content h6 {
  margin: 2rem 0 1rem 0;
  font-weight: 600;
  color: var(--text-primary);
}

.article-content h1 { font-size: 2rem; }
.article-content h2 { font-size: 1.75rem; }
.article-content h3 { font-size: 1.5rem; }
.article-content h4 { font-size: 1.25rem; }

.article-content p {
  margin-bottom: 1.5rem;
}

.article-content ul,
.article-content ol {
  margin: 1rem 0 1.5rem 2rem;
}

.article-content li {
  margin-bottom: 0.5rem;
}

.article-content blockquote {
  border-left: 4px solid var(--primary-color);
  padding-left: 1rem;
  margin: 1.5rem 0;
  font-style: italic;
  color: var(--text-secondary);
}

.article-content code {
  background: var(--bg-tertiary);
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius);
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 0.875rem;
}

.article-content pre {
  background: var(--bg-secondary);
  padding: 1.5rem;
  border-radius: var(--radius-lg);
  overflow-x: auto;
  margin: 1.5rem 0;
  border: 1px solid var(--border-color);
}

.article-content pre code {
  background: none;
  padding: 0;
}

.article-content img {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius);
  margin: 1.5rem 0;
}

.article-content a {
  color: var(--primary-color);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}

.article-content a:hover {
  text-decoration-thickness: 2px;
}

/* Navigation between posts */
.post-navigation {
  display: flex;
  justify-content: space-between;
  gap: 2rem;
  margin: 3rem 0;
  padding: 2rem 0;
  border-top: 1px solid var(--border-color);
}

.nav-post {
  flex: 1;
  text-decoration: none;
  color: var(--text-secondary);
  padding: 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  transition: all 0.2s;
}

.nav-post:hover {
  border-color: var(--primary-color);
  color: var(--primary-color);
}

.nav-post-label {
  font-size: 0.875rem;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nav-post-title {
  font-weight: 600;
}

.nav-post.next {
  text-align: right;
}

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin: 2rem 0;
}

.pagination a,
.pagination span {
  padding: 0.5rem 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  text-decoration: none;
  color: var(--text-secondary);
  transition: all 0.2s;
}

.pagination a:hover {
  border-color: var(--primary-color);
  color: var(--primary-color);
}

.pagination .current {
  background: var(--primary-color);
  color: white;
  border-color: var(--primary-color);
}

/* Loading and states */
.loading {
  text-align: center;
  padding: 2rem;
  color: var(--text-muted);
}

.error {
  text-align: center;
  padding: 2rem;
  color: #dc2626;
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: var(--radius);
  margin: 1rem 0;
}

.empty-state {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--text-muted);
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 2rem 0;
  margin-top: 3rem;
  text-align: center;
  color: var(--text-muted);
}

.footer a {
  color: var(--primary-color);
  text-decoration: none;
}

/* Responsive design */
@media (max-width: 768px) {
  .container {
    padding: 0 0.75rem;
  }

  .header-content {
    flex-direction: column;
    gap: 1rem;
  }

  .nav {
    gap: 1rem;
  }

  .search-controls {
    flex-direction: column;
  }

  .search-input {
    min-width: auto;
  }

  .article-title {
    font-size: 2rem;
  }

  .article-meta {
    flex-direction: column;
    gap: 0.5rem;
  }

  .post-navigation {
    flex-direction: column;
  }

  .nav-post.next {
    text-align: left;
  }
}

@media (max-width: 480px) {
  .article-title {
    font-size: 1.75rem;
  }

  .post-title {
    font-size: 1.25rem;
  }

  .article-content {
    font-size: 1rem;
  }
}

/* Utilities */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.text-center { text-align: center; }
.mt-4 { margin-top: 1rem; }
.mb-4 { margin-bottom: 1rem; }
.hidden { display: none; }

// Blog system main JavaScript
class BlogSystem {
  constructor() {
    this.siteConfig = null;
    this.posts = [];
    this.allPosts = [];
    this.currentPage = 1;
    this.postsPerPage = 10;
    this.currentTag = null;
    this.currentYear = null;
    this.currentMonth = null;
    this.searchQuery = '';

    this.init();
  }

  async init() {
    try {
      await this.loadSiteConfig();
      await this.loadPosts();
      this.initializeRouting();
      this.bindEvents();
    } catch (error) {
      console.error('Failed to initialize blog system:', error);
      this.showError('Failed to load blog. Please try again later.');
    }
  }

  async loadSiteConfig() {
    try {
      const response = await fetch('./assets/meta/site.json');
      this.siteConfig = await response.json();
      this.postsPerPage = this.siteConfig.pagination?.postsPerPage || 10;
      this.updateSiteTitle();
    } catch (error) {
      console.error('Failed to load site config:', error);
      this.siteConfig = this.getDefaultSiteConfig();
    }
  }

  getDefaultSiteConfig() {
    return {
      title: 'My Blog',
      subtitle: 'A personal blog',
      description: 'Personal thoughts and experiences',
      author: { name: 'Anonymous' }
    };
  }

  async loadPosts() {
    try {
      // Try to load from index.json first (if exists)
      try {
        const response = await fetch('./assets/meta/index.json');
        if (response.ok) {
          this.allPosts = await response.json();
          this.posts = [...this.allPosts];
          return;
        }
      } catch (e) {
        // Fall back to discovering posts
      }

      // Discover posts by trying common filenames
      await this.discoverPosts();
    } catch (error) {
      console.error('Failed to load posts:', error);
      this.showError('Failed to load posts.');
    }
  }

  async discoverPosts() {
    // This is a simplified discovery method
    // In production, you might want to use GitHub API or generate index.json
    const posts = [];
    const currentYear = new Date().getFullYear();

    // Try to discover posts from the last 2 years
    for (let year = currentYear; year >= currentYear - 1; year--) {
      for (let month = 12; month >= 1; month--) {
        for (let day = 31; day >= 1; day--) {
          const dateStr = `${year}-${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;

          // Try common slug patterns
          const commonSlugs = ['hello-world', 'first-post', 'welcome', 'introduction'];
          for (const slug of commonSlugs) {
            try {
              const filename = `${dateStr}--${slug}.md`;
              const response = await fetch(`./assets/posts/${filename}`);
              if (response.ok) {
                const content = await response.text();
                const post = this.parsePost(content, filename);
                if (post) {
                  posts.push(post);
                }
              }
            } catch (e) {
              // Continue trying
            }
          }
        }
      }
    }

    this.allPosts = posts.sort((a, b) => new Date(b.date) - new Date(a.date));
    this.posts = [...this.allPosts];
  }

  parsePost(content, filename) {
    const frontMatterMatch = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);

    if (!frontMatterMatch) {
      return null;
    }

    const frontMatter = this.parseFrontMatter(frontMatterMatch[1]);
    const bodyContent = frontMatterMatch[2];

    // Extract date and slug from filename
    const filenameMatch = filename.match(/(\d{4}-\d{2}-\d{2})--(.+)\.md$/);
    const fileDate = filenameMatch ? filenameMatch[1] : null;
    const fileSlug = filenameMatch ? filenameMatch[2] : filename.replace('.md', '');

    const post = {
      slug: fileSlug,
      title: frontMatter.title || this.extractTitleFromContent(bodyContent) || 'Untitled',
      date: frontMatter.date || fileDate || new Date().toISOString().split('T')[0],
      tags: frontMatter.tags || [],
      series: frontMatter.series || null,
      description: frontMatter.description || this.extractExcerpt(bodyContent),
      cover: frontMatter.cover || null,
      content: bodyContent,
      filename: filename,
      readingTime: this.calculateReadingTime(bodyContent)
    };

    return post;
  }

  parseFrontMatter(yamlContent) {
    const result = {};
    const lines = yamlContent.split('\n');

    for (const line of lines) {
      const match = line.match(/^([^:]+):\s*(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Handle arrays (tags)
        if (value.startsWith('[') && value.endsWith(']')) {
          value = value.slice(1, -1).split(',').map(s => s.trim().replace(/['"]/g, ''));
        } else {
          // Remove quotes
          value = value.replace(/^['"]|['"]$/g, '');
        }

        result[key] = value;
      }
    }

    return result;
  }

  extractTitleFromContent(content) {
    const match = content.match(/^#\s+(.+)$/m);
    return match ? match[1] : null;
  }

  extractExcerpt(content, maxLength = 160) {
    // Remove markdown syntax and get plain text
    const plainText = content
      .replace(/^#.*$/gm, '') // Remove headers
      .replace(/\*\*(.*?)\*\*/g, '$1') // Remove bold
      .replace(/\*(.*?)\*/g, '$1') // Remove italic
      .replace(/`(.*?)`/g, '$1') // Remove inline code
      .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // Remove links
      .replace(/\n/g, ' ')
      .trim();

    return plainText.length > maxLength 
      ? plainText.substring(0, maxLength) + '...'
      : plainText;
  }

  calculateReadingTime(content) {
    const wordsPerMinute = 200;
    const words = content.split(/\s+/).length;
    const minutes = Math.ceil(words / wordsPerMinute);
    return `${minutes} min read`;
  }

  initializeRouting() {
    const hash = window.location.hash;

    if (hash.startsWith('#/post/')) {
      const slug = hash.replace('#/post/', '');
      this.showPost(slug);
    } else if (hash.startsWith('#/tag/')) {
      const tag = hash.replace('#/tag/', '');
      this.filterByTag(tag);
    } else if (hash.startsWith('#/archives')) {
      this.showArchives(hash);
    } else if (hash.startsWith('#/search')) {
      const params = new URLSearchParams(hash.split('?')[1]);
      const query = params.get('q') || '';
      this.search(query);
    } else {
      this.showPostList();
    }
  }

  bindEvents() {
    // Search input
    const searchInput = document.getElementById('search-input');
    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        this.search(e.target.value);
      });
    }

    // Tag filter
    const tagFilter = document.getElementById('tag-filter');
    if (tagFilter) {
      tagFilter.addEventListener('change', (e) => {
        if (e.target.value) {
          this.filterByTag(e.target.value);
        } else {
          this.clearFilters();
        }
      });
    }

    // Hash change for routing
    window.addEventListener('hashchange', () => {
      this.initializeRouting();
    });

    // Back to top button
    window.addEventListener('scroll', () => {
      const backToTop = document.getElementById('back-to-top');
      if (backToTop) {
        backToTop.style.display = window.scrollY > 500 ? 'block' : 'none';
      }
    });
  }

  updateSiteTitle(pageTitle = null) {
    const baseTitle = this.siteConfig.title;
    document.title = pageTitle ? `${pageTitle} - ${baseTitle}` : baseTitle;
  }

  showPostList(page = 1) {
    this.currentPage = page;

    const startIndex = (page - 1) * this.postsPerPage;
    const endIndex = startIndex + this.postsPerPage;
    const postsToShow = this.posts.slice(startIndex, endIndex);

    const content = document.getElementById('content');
    if (!content) return;

    const html = `
      <div class="posts-section">
        <div class="search-controls">
          <input type="text" id="search-input" class="search-input" placeholder="Search posts..." value="${this.searchQuery}">
          <select id="tag-filter" class="filter-select">
            <option value="">All Tags</option>
            ${this.getAllTags().map(tag => 
              `<option value="${tag}" ${this.currentTag === tag ? 'selected' : ''}>${tag}</option>`
            ).join('')}
          </select>
        </div>

        ${this.currentTag || this.searchQuery ? `
          <div class="active-filters">
            ${this.currentTag ? `<span class="filter-tag">Tag: ${this.currentTag} <button onclick="blog.clearFilters()">&times;</button></span>` : ''}
            ${this.searchQuery ? `<span class="filter-tag">Search: "${this.searchQuery}" <button onclick="blog.clearFilters()">&times;</button></span>` : ''}
          </div>
        ` : ''}

        <div class="posts-grid">
          ${postsToShow.map(post => this.renderPostCard(post)).join('')}
        </div>

        ${this.posts.length === 0 ? '<div class="empty-state">No posts found matching your criteria.</div>' : ''}

        ${this.renderPagination()}
      </div>
    `;

    content.innerHTML = html;
    this.bindEvents();
    this.updateSiteTitle();
  }

  renderPostCard(post) {
    return `
      <article class="post-card">
        <div class="post-card-header">
          <h2 class="post-title">
            <a href="#/post/${post.slug}">${post.title}</a>
          </h2>
          <div class="post-meta">
            <span class="post-date">📅 ${this.formatDate(post.date)}</span>
            <span class="post-reading-time">⏱️ ${post.readingTime}</span>
          </div>
        </div>

        ${post.description ? `<p class="post-excerpt">${post.description}</p>` : ''}

        ${post.tags.length > 0 ? `
          <div class="post-tags">
            ${post.tags.map(tag => `<a href="#/tag/${tag}" class="tag">${tag}</a>`).join('')}
          </div>
        ` : ''}
      </article>
    `;
  }

  renderPagination() {
    const totalPages = Math.ceil(this.posts.length / this.postsPerPage);

    if (totalPages <= 1) return '';

    let pagination = '<div class="pagination">';

    // Previous button
    if (this.currentPage > 1) {
      pagination += `<a href="#" onclick="blog.showPostList(${this.currentPage - 1})">&laquo; Previous</a>`;
    }

    // Page numbers
    for (let i = 1; i <= totalPages; i++) {
      if (i === this.currentPage) {
        pagination += `<span class="current">${i}</span>`;
      } else {
        pagination += `<a href="#" onclick="blog.showPostList(${i})">${i}</a>`;
      }
    }

    // Next button
    if (this.currentPage < totalPages) {
      pagination += `<a href="#" onclick="blog.showPostList(${this.currentPage + 1})">Next &raquo;</a>`;
    }

    pagination += '</div>';
    return pagination;
  }

  async showPost(slug) {
    const post = this.allPosts.find(p => p.slug === slug);

    if (!post) {
      this.showError('Post not found.');
      return;
    }

    let content = post.content;

    // If we don't have the full content, load it
    if (!content) {
      try {
        const response = await fetch(`./assets/posts/${post.filename}`);
        const fullContent = await response.text();
        const parsedPost = this.parsePost(fullContent, post.filename);
        content = parsedPost.content;
      } catch (error) {
        this.showError('Failed to load post content.');
        return;
      }
    }

    const contentDiv = document.getElementById('content');
    if (!contentDiv) return;

    const renderedContent = this.renderMarkdown(content);
    const navigation = this.getPostNavigation(slug);

    const html = `
      <article class="article">
        <header class="article-header">
          <h1 class="article-title">${post.title}</h1>
          <div class="article-meta">
            <span class="post-date">📅 ${this.formatDate(post.date)}</span>
            <span class="post-reading-time">⏱️ ${post.readingTime}</span>
          </div>
          ${post.tags.length > 0 ? `
            <div class="article-tags">
              ${post.tags.map(tag => `<a href="#/tag/${tag}" class="tag">${tag}</a>`).join('')}
            </div>
          ` : ''}
        </header>

        <div class="article-content">
          ${renderedContent}
        </div>
      </article>

      ${navigation}
    `;

    contentDiv.innerHTML = html;
    this.updateSiteTitle(post.title);

    // Scroll to top
    window.scrollTo(0, 0);
  }

  getPostNavigation(currentSlug) {
    const currentIndex = this.allPosts.findIndex(p => p.slug === currentSlug);
    if (currentIndex === -1) return '';

    const prevPost = this.allPosts[currentIndex + 1];
    const nextPost = this.allPosts[currentIndex - 1];

    if (!prevPost && !nextPost) return '';

    return `
      <nav class="post-navigation">
        ${prevPost ? `
          <a href="#/post/${prevPost.slug}" class="nav-post prev">
            <div class="nav-post-label">Previous Post</div>
            <div class="nav-post-title">${prevPost.title}</div>
          </a>
        ` : '<div></div>'}

        ${nextPost ? `
          <a href="#/post/${nextPost.slug}" class="nav-post next">
            <div class="nav-post-label">Next Post</div>
            <div class="nav-post-title">${nextPost.title}</div>
          </a>
        ` : '<div></div>'}
      </nav>
    `;
  }

  renderMarkdown(content) {
    // Simple markdown rendering - in production you'd use a library like marked.js
    return content
      .replace(/^### (.*$)/gm, '<h3>$1</h3>')
      .replace(/^## (.*$)/gm, '<h2>$1</h2>')
      .replace(/^# (.*$)/gm, '<h1>$1</h1>')
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(/`(.*?)`/g, '<code>$1</code>')
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')
      .replace(/^> (.*$)/gm, '<blockquote>$1</blockquote>')
      .replace(/\n\n/g, '</p><p>')
      .replace(/^/, '<p>')
      .replace(/$/, '</p>')
      .replace(/<p><\/p>/g, '')
      .replace(/<p>(<h[1-6]>)/g, '$1')
      .replace(/(<\/h[1-6]>)<\/p>/g, '$1')
      .replace(/<p>(<blockquote>)/g, '$1')
      .replace(/(<\/blockquote>)<\/p>/g, '$1');
  }

  filterByTag(tag) {
    this.currentTag = tag;
    this.posts = this.allPosts.filter(post => post.tags.includes(tag));
    this.currentPage = 1;
    this.showPostList();
    window.location.hash = `#/tag/${tag}`;
  }

  search(query) {
    this.searchQuery = query.trim();

    if (!this.searchQuery) {
      this.posts = [...this.allPosts];
    } else {
      const lowerQuery = this.searchQuery.toLowerCase();
      this.posts = this.allPosts.filter(post => 
        post.title.toLowerCase().includes(lowerQuery) ||
        post.description.toLowerCase().includes(lowerQuery) ||
        post.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
      );
    }

    this.currentPage = 1;
    this.showPostList();

    if (this.searchQuery) {
      window.location.hash = `#/search?q=${encodeURIComponent(this.searchQuery)}`;
    }
  }

  clearFilters() {
    this.currentTag = null;
    this.searchQuery = '';
    this.posts = [...this.allPosts];
    this.currentPage = 1;
    this.showPostList();
    window.location.hash = '#/';
  }

  getAllTags() {
    const tags = new Set();
    this.allPosts.forEach(post => {
      post.tags.forEach(tag => tags.add(tag));
    });
    return Array.from(tags).sort();
  }

  formatDate(dateString) {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });
  }

  showError(message) {
    const content = document.getElementById('content');
    if (content) {
      content.innerHTML = `<div class="error">${message}</div>`;
    }
  }

  showLoading() {
    const content = document.getElementById('content');
    if (content) {
      content.innerHTML = '<div class="loading">Loading...</div>';
    }
  }
}

